#!/usr/bin/env python3
"""Regenerate bedrock-meter/hooks/prices.ts from the AWS price list.

Reads Amazon Bedrock's on-demand Claude prices (AmazonBedrockFoundationModels,
us-east-1) from AWS's public price list, which needs no credentials, and writes
them as bedrock-meter's price table. When a price changed, it bumps the patch
version in bedrock-meter's plugin.json, so merging the change ships it, and
prints what changed (the body of the weekly workflow's pull request).

    python3 .github/scripts/bedrock_prices.py              # fetch from AWS
    python3 .github/scripts/bedrock_prices.py offer.json   # a file already fetched

Exit code 0 either way; the workflow reads `git diff` to tell a change.
"""
import json
import re
import sys
import urllib.request
from pathlib import Path

HOST = 'https://pricing.us-east-1.amazonaws.com'
INDEX = f'{HOST}/offers/v1.0/aws/AmazonBedrockFoundationModels/current/region_index.json'
REGION = 'us-east-1'

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'bedrock-meter' / 'hooks' / 'prices.ts'
MANIFEST = ROOT / 'bedrock-meter' / '.claude-plugin' / 'plugin.json'

KINDS = {
    'Input tokens': 'input',
    'Output tokens': 'output',
    'Prompt cache read input tokens': 'cacheRead',
    'Prompt cache write input tokens': 'cacheWrite',
}
# Tiers Claude Code does not use: 1-hour cache writes, latency-optimized, batch.
SKIP = re.compile(r'1h|latencyoptimized|batch|flex|priority', re.I)


def fetch(url: str):
    with urllib.request.urlopen(url, timeout=60) as r:
        return json.load(r)


def load(argv):
    if len(argv) > 1:
        return json.loads(Path(argv[1]).read_text())
    version = fetch(INDEX)['regions'][REGION]['currentVersionUrl']
    return fetch(HOST + version)


def family_of(model: str):
    """`Claude Opus 5.5` -> `opus-5-5`, `Claude 3.5 Haiku` -> `3-5-haiku`, as model ids name them."""
    m = re.fullmatch(r'Claude (Opus|Sonnet|Haiku|Fable|Mythos) (\d+(?:\.\d+)?)', model)
    if m:
        return f"{m[1].lower()}-{m[2].replace('.', '-')}"
    m = re.fullmatch(r'Claude (\d)(?:\.(\d))? (Opus|Sonnet|Haiku)(?: v2)?', model)
    if m:
        return '-'.join(x for x in (m[1], m[2], m[3].lower()) if x)
    return None  # Claude Instant, Claude (100K), previews: not served to Claude Code


def tiers(offer):
    terms = offer['terms']['OnDemand']
    out = {}
    for sku, product in offer['products'].items():
        a = product['attributes']
        family = family_of(a.get('model', ''))
        kind = KINDS.get(a.get('inferenceType', ''))
        usage = a.get('usagetype', '')
        if a.get('feature') != 'On-demand Inference' or not family or not kind or SKIP.search(usage):
            continue
        tier = ('global' if 'global' in usage.lower() else 'regional') + ('Long' if 'long' in usage.lower() else '')
        for term in terms.get(sku, {}).values():
            for dim in term['priceDimensions'].values():
                if dim.get('unit') != '1M tokens':
                    continue
                usd = float(dim['pricePerUnit']['USD'])
                held = out.setdefault(family, {}).setdefault(tier, {})
                if kind in held and held[kind] != usd:
                    print(f'warning: {family} {tier} {kind}: {held[kind]} and {usd}; keeping the first', file=sys.stderr)
                held.setdefault(kind, usd)
    # A tier missing one of the four prices is not one to bill by.
    return {
        f: {t: p for t, p in ts.items() if len(p) == len(KINDS)}
        for f, ts in out.items()
        if any(len(p) == len(KINDS) for p in ts.values())
    }


def num(x: float) -> str:
    return f'{x:.6f}'.rstrip('0').rstrip('.')


def render(rows, published: str) -> str:
    lines = [
        '// Generated by .github/scripts/bedrock_prices.py from the AWS price list',
        f'// (AmazonBedrockFoundationModels, {REGION}). Rerun it, or edit by hand.',
        '// USD per million tokens, on-demand: `global` for global. inference profiles,',
        '// `regional` for in-region and geo (us., eu., apac.) ones; `*Long` past the',
        "// model's long-context threshold. Cache writes are the 5-minute TTL's.",
        "import type { Row } from './pricing'",
        '',
        f"export const PUBLISHED = '{published}'",
        '',
        '// Longest family first, so `opus-5-5` wins over `opus-5`.',
        'export const ROWS: Row[] = [',
    ]
    for family in sorted(rows, key=lambda f: (-len(f), f)):
        lines.append('  {')
        lines.append(f"    family: '{family}',")
        for tier in ('global', 'regional', 'globalLong', 'regionalLong'):
            p = rows[family].get(tier)
            if p:
                body = ', '.join(f'{k}: {num(p[k])}' for k in ('input', 'output', 'cacheRead', 'cacheWrite'))
                lines.append(f'    {tier}: {{ {body} }},')
        lines.append('  },')
    lines.append(']')
    return '\n'.join(lines) + '\n'


def table_of(text: str) -> str:
    return text[text.find('export const ROWS'):] if text else ''


def changes(old: str, new: str):
    """One line per family whose prices moved, came or went."""
    def rows(text):
        return {m[1]: m[2] for m in re.finditer(r"family: '([^']+)',\n((?:    .*\n)*?)  \}", text)}
    before, after = rows(old), rows(new)
    out = []
    for f in sorted(set(before) | set(after)):
        if f not in before:
            out.append(f'- added `{f}`')
        elif f not in after:
            out.append(f'- removed `{f}`')
        elif before[f] != after[f]:
            out.append(f'- `{f}`:\n```diff\n' + ''.join(f'-{l}\n' for l in before[f].splitlines()) + ''.join(f'+{l}\n' for l in after[f].splitlines()) + '```')
    return out


def bump(path: Path):
    manifest = json.loads(path.read_text())
    major, minor, patch = (int(x) for x in manifest['version'].split('.'))
    manifest['version'] = f'{major}.{minor}.{patch + 1}'
    path.write_text(json.dumps(manifest, indent=2) + '\n')
    return manifest['version']


def main(argv):
    offer = load(argv)
    rows = tiers(offer)
    if not rows:
        sys.exit('no Claude prices found: the price list format may have changed')
    new = render(rows, offer.get('publicationDate', 'unknown'))
    old = OUT.read_text() if OUT.exists() else ''
    if table_of(old) == table_of(new):
        print('Bedrock prices unchanged.')
        return
    OUT.write_text(new)
    version = bump(MANIFEST) if old else None
    print(f"AWS price list published {offer.get('publicationDate', 'unknown')}" + (f'; bedrock-meter bumped to {version}.' if version else '.'))
    print()
    print('\n'.join(changes(old, new)))


if __name__ == '__main__':
    main(sys.argv)
